CREATE OR REPLACE FUNCTION public.activation_require_fee() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='provider_connections' AND NEW.provider<>'asaas' THEN RETURN NEW; END IF; IF NOT public.activation_fee_paid(NEW.tenant_id) THEN RAISE EXCEPTION 'activation_fee_required'; END IF; RETURN NEW; END $$;
ALTER TABLE public.activation_documents ADD COLUMN IF NOT EXISTS superseded_at timestamptz;
CREATE FUNCTION public.activation_document_version() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN UPDATE public.activation_documents SET superseded_at=now() WHERE tenant_id=NEW.tenant_id AND kind=NEW.kind AND superseded_at IS NULL; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.activation_document_version() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER activation_document_version BEFORE INSERT ON public.activation_documents FOR EACH ROW EXECUTE FUNCTION public.activation_document_version();
ALTER POLICY kyc_paid_access ON storage.objects USING(bucket_id<>'kyc-documents' OR CASE WHEN (storage.foldername(name))[1] ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN public.activation_fee_paid(((storage.foldername(name))[1])::uuid) AND public.is_tenant_member(((storage.foldername(name))[1])::uuid) ELSE false END) WITH CHECK(bucket_id<>'kyc-documents');
CREATE FUNCTION public.activation_kyc_storage_gate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t text; BEGIN IF NEW.bucket_id='kyc-documents' THEN t:=(storage.foldername(NEW.name))[1]; IF t IS NULL OR t !~ '^[0-9a-fA-F-]{36}$' OR NOT public.activation_fee_paid(t::uuid) THEN RAISE EXCEPTION 'activation_fee_required'; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.activation_kyc_storage_gate() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER activation_kyc_storage_gate BEFORE INSERT OR UPDATE ON storage.objects FOR EACH ROW EXECUTE FUNCTION public.activation_kyc_storage_gate();
CREATE OR REPLACE FUNCTION public.activation_fee_paid(_tenant uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.activation_fee_payments WHERE tenant_id=_tenant AND status='confirmed' AND confirmed_amount_cents=1990 AND confirmed_at IS NOT NULL) AND (auth.role()='service_role' OR public.is_tenant_member(_tenant)); $$;
COMMENT ON COLUMN public.activation_documents.superseded_at IS 'Historical versions retained; only NULL is the current document.';